export function isChromiumScreenshotUnavailable(error) {
  return (
    error instanceof Error &&
    /^(?:page\.screenshot|cdpSession\.send): Protocol error \(Page\.captureScreenshot\): Unable to capture screenshot$/.test(
      error.message.split("\n", 1)[0],
    )
  );
}

export async function captureBrowserObservation(page, capture, redact, signal) {
  const first = await captureFrame(page, capture, redact);
  if (first.page) return first;
  // A redirect can settle between frames. Keep the latest image even if the tab keeps changing.
  try {
    return await captureFrame(page, capture, redact);
  } catch (error) {
    signal?.throwIfAborted();
    if (page.isClosed() || !isChromiumScreenshotUnavailable(error)) throw error;
    return first;
  }
}

async function captureFrame(page, capture, redact) {
  const url = page.url();
  const title = await page.title();
  const bytes = await capture(page);
  const capturedAt = new Date().toISOString();
  const currentTitle = await page.title();
  const tab =
    page.url() === url && currentTitle === title
      ? { url: redact(url), title: redact(title) }
      : null;
  const address = new URL(url);
  const route =
    address.origin === "null" ? url : address.origin + address.pathname;
  return {
    bytes,
    capturedAt,
    page: tab,
    viewLocation: tab ? redact(route) : undefined,
  };
}

export function browserObservationText(metadata) {
  return { type: "input_text", text: JSON.stringify(metadata) };
}
